async function seedDatabase() {
  try {
    // Seed Categories
    await Category.deleteMany({});
    await Category.insertMany(CATEGORIES);
    console.log('🌱 Seeded Categories');

    // Seed Products — Sync full staple grocery products catalog
    await Product.deleteMany({});
    await Product.insertMany(PRODUCTS);
    console.log(`🌱 Seeded ${PRODUCTS.length} Pantry & Grocery Products into MongoDB Atlas`);

    // Seed Suppliers
    if ((await Supplier.countDocuments()) === 0) {
      await Supplier.insertMany(SUPPLIERS);
      console.log('🌱 Seeded Suppliers');
    }

    // Seed Purchase Orders
    if ((await PurchaseOrder.countDocuments()) === 0) {
      await PurchaseOrder.insertMany(PURCHASE_ORDERS);
      console.log('🌱 Seeded Purchase Orders');
    }

    // Clean sample mock customers from database
    await Customer.deleteMany({
      email: { $in: ['ananya.s@gmail.com', 'ramesh.k@live.com', 'kavitha.r@ymail.com', 'siddharth@outlook.com', 'priyanair@me.com'] }
    });

    // Seed Staff Users
    if ((await User.countDocuments()) === 0) {
      for (const usr of USERS) {
        const newUser = new User(usr);
        await newUser.save();
      }
      console.log('🌱 Seeded Staff Users');
    }

    // Seed Deliveries
    if ((await Delivery.countDocuments()) === 0) {
      await Delivery.insertMany(DELIVERIES);
      console.log('🌱 Seeded Deliveries');
    }

    // Seed Stock Batches
    if ((await StockBatch.countDocuments()) === 0) {
      await StockBatch.insertMany(STOCK_BATCHES);
      console.log('🌱 Seeded Stock Batches');
    }

    // Seed Store Settings
    if ((await StoreSetting.countDocuments()) === 0) {
      await StoreSetting.insertMany(SETTINGS);
      console.log('🌱 Seeded Store Settings');
    }

    console.log('🎉 Database seeding completed successfully!');
  } catch (err) {
    console.error('❌ Seeding failed:', err.message);
    throw err;
  }
}

// If run directly from terminal: `node seed.js`
if (require.main === module) {
  mongoose.connect(process.env.MONGO_URI)
    .then(async () => {
      console.log('⚡ Connected to MongoDB Atlas for CLI seeding...');
      await seedDatabase();
      mongoose.connection.close();
      process.exit(0);
    })
    .catch(err => {
      console.error('❌ CLI seeding connection error:', err.message);
      process.exit(1);
    });
}

module.exports = seedDatabase;
